import { Fragment, useState } from 'react';
import type { ChangeEvent, FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheet';
import { useClaims } from '../claims/claims';
import { GRADES, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { useFloor, useLate } from '../settings/settings';
import { personDueTotal, rateOn, ratesKey, sheetDueTotal, useRates } from './rates';
import type { Rate } from './rates';

const PCT = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The sheet's rates — per grade the one in force on the sheet's today, then each rate with its
 *  from-date and to-date — and the form that sets one (for a grade and from-date, replacing any it had). */
function Rates({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (body: { grade: string; rate: string; from: string; to: string }) =>
      putJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates/${body.grade}`, {
        user,
        rate: body.rate,
        from: body.from || null,
        to: body.to || null,
      }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
      setPct('');
      setFrom('');
      setTo('');
    },
    onError: () =>
      setError('Could not set this rate: it must be a percent, 0.00 to 999.99, with up to two decimals, from a date yyyy-mm-dd or none, to a date not before it or none.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!PCT.test(pct.trim())) {
      setError('The rate must be a percent, 0.00 to 999.99, with up to two decimals.');
      return;
    }
    if (from.trim() !== '' && !DATE.test(from.trim())) {
      setError('The from-date must be a date, yyyy-mm-dd, or left empty.');
      return;
    }
    if (to.trim() !== '' && !DATE.test(to.trim())) {
      setError('The to-date must be a date, yyyy-mm-dd, or left empty.');
      return;
    }
    if (to.trim() !== '' && from.trim() !== '' && to.trim() < from.trim()) {
      setError('The to-date must not be before the from-date.');
      return;
    }
    if (!once.start()) return;
    save.mutate({ grade, rate: pct.trim(), from: from.trim(), to: to.trim() });
  };

  const change = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    set(e.target.value);
    setError('');
  };

  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <form data-testid="rate-form" onSubmit={submit}>
        <label>
          Grade{' '}
          <select data-testid="rate-form-grade" value={grade} onChange={change(setGrade)}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input data-testid="rate-form-pct" placeholder="0.00" value={pct} onChange={change(setPct)} />
        </label>{' '}
        <label>
          From{' '}
          <input data-testid="rate-form-from" placeholder="yyyy-mm-dd (optional)" value={from} onChange={change(setFrom)} />
        </label>{' '}
        <label>
          To{' '}
          <input data-testid="rate-form-to" placeholder="yyyy-mm-dd (optional)" value={to} onChange={change(setTo)} />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && (
          <p data-testid="rate-form-error" role="alert">
            {error}
          </p>
        )}
      </form>
      <table>
        <tbody>
          {GRADES.map((g) => {
            const undated = rates.find((r) => r.grade === g && r.from === null);
            const dated = rates.filter((r) => r.grade === g && r.from !== null);
            return (
              <Fragment key={g}>
                <tr>
                  <th>{g}</th>
                  <td>
                    In force today <span data-testid={`rate-current-${g}`}>{rateOn(rates, g, today) ?? 'n/a'}</span>
                  </td>
                </tr>
                <tr data-testid={`rate-row-${g}-start`}>
                  <td data-testid="rate-from">from the start</td>
                  <td data-testid="rate-pct">{undated?.rate ?? 'n/a'}</td>
                  <td data-testid="rate-to">{undated?.to ?? ''}</td>
                </tr>
                {dated.map((r) => (
                  <tr key={r.from} data-testid={`rate-row-${g}-${r.from}`}>
                    <td data-testid="rate-from">{r.from}</td>
                    <td data-testid="rate-pct">{r.rate}</td>
                    <td data-testid="rate-to">{r.to ?? ''}</td>
                  </tr>
                ))}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </section>
  );
}

/** A person's due-total: the figures of their claims that count added up (see personDueTotal). */
function PersonDueTotal({ sheetId, person }: { sheetId: string; user: string; person: Person }) {
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  return <td data-testid="person-due-total">{personDueTotal(person, claims, rates, today, floor, late)}</td>;
}

/** The sheet's due-total: every person's due-total added up, skipping n/a. */
function DueTotal({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  return (
    <p>
      Due total <strong data-testid="rollup-due-total">{sheetDueTotal(people, claims, rates, today, floor, late)}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: Rates }),
  SheetBody.fill({ order: 21, Component: DueTotal }),
  PersonRow.fill({ order: 20, Component: PersonDueTotal }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { gradeOn, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDue, rateOn, sumDue, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

/** A person's patrons (their names, sorted), their backing — the patrons' due-totals added up, skipping n/a;
 *  0.00 with no patrons — and the picker that names one more. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const claims = live(useClaims(sheetId).data ?? [], people);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const patrons = (usePatrons(sheetId).data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined)
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const backing = sumDue(
    patrons.map((p) =>
      personDue(
        claims.filter((c) => c.personId === p.id),
        (d) => rateOn(rates, gradeOn(p, d), d),
        rateOn(rates, gradeOn(p, today), today),
        floor,
        late,
      ),
    ),
  );
  const [chosen, setChosen] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/patrons`, { user, patronId }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
      setChosen('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not name this patron for ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      Patrons <span data-testid="person-patrons">{patrons.map((p) => p.name).join(', ')}</span>{' '}
      Backing <span data-testid="person-backing">{backing}</span>{' '}
      <select
        data-testid="person-patron-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          setError('');
        }}
      >
        <option value="">Patron…</option>
        {people.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-patron-add"
        disabled={add.isPending}
        onClick={() => {
          setError('');
          if (chosen === '') {
            setError('Choose a person to name as a patron.');
            return;
          }
          if (!once.start()) return;
          add.mutate(Number(chosen));
        }}
      >
        Add patron
      </button>
      {error && (
        <p data-testid="person-patron-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 46, Component: PersonPatrons });
import { SheetBody } from '../../slots/defs/sheet';
import { STATUSES, useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { overdueDues, sheetDueTotal, sumDue, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';

/** The sheet's header counters, shown above everything else: its people (retired ones included), its claims
 *  per status (as the summary counts them) and its due-total and overdue-total (as the rollup shows them). */
function Header({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  return (
    <header data-testid="header">
      <span>
        People <strong data-testid="header-people-count">{people.length}</strong>
      </span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}
          {s} <strong data-testid={`header-claims-${s}-count`}>{claims.filter((c) => c.status === s).length}</strong>
        </span>
      ))}{' '}
      <span>
        Due total <strong data-testid="header-due-total">{sheetDueTotal(people, claims, rates, today, floor, late)}</strong>
      </span>{' '}
      <span>
        Overdue total <strong data-testid="header-overdue-total">{sumDue(overdueDues(claims, people, rates, late, floor))}</strong>
      </span>
    </header>
  );
}

export const contribution = SheetBody.fill({ order: -1, Component: Header });

